// Lê o evento que a Meta mandou. Cada mensagem do cliente vira um item com o texto
// que a Lia vai ler. Recibos de entrega (enviada, entregue, lida, falhou) viram itens "status".
const corpo = $('Recebe do WhatsApp').first().json.body || {};

const artigo = (nome) => (/^\S*a\b/i.test(String(nome).trim()) ? 'a' : 'o');
// Botões montados pelo n8n levam "acao|codigo|nome" no id (ex.: "quero|OLD-P97|Camisa Flamengo")
const decodificar = (id, titulo) => {
  const p = String(id || '').split('|');
  if (p.length >= 3) {
    const nome = p.slice(2).join('|');
    const a = artigo(nome);
    if (p[0] === 'quero') return 'Quero ' + a + ' ' + nome;
    if (p[0] === 'fotos') return 'Quero ver mais fotos d' + a + ' ' + nome;
    if (p[0] === 'tam') return 'Qual tamanho fica bom em mim n' + a + ' ' + nome + '?';
    if (p[0] === 'provar') return 'Quero ver como ' + a + ' ' + nome + ' fica em mim';
  }
  return titulo;
};

const traduzir = (m) => {
  switch (m.type) {
    case 'text':
      return (m.text || {}).body || '';
    case 'interactive': {
      const i = m.interactive || {};
      if (i.type === 'button_reply') return decodificar(i.button_reply.id, i.button_reply.title);
      if (i.type === 'list_reply') return decodificar(i.list_reply.id, i.list_reply.title);
      if (i.type === 'nfm_reply') {
        // Resposta do Flow "Descubra seu tamanho": vira a mesma frase que a página de chat envia
        let r = {};
        try { r = JSON.parse((i.nfm_reply || {}).response_json || '{}'); } catch (e) { r = {}; }
        if (String(r.idade || '').trim()) return 'Idade da criança para a ' + r.nome + ': ' + r.idade + ' anos';
        if (String(r.altura || '').trim()) return 'Minhas medidas para a ' + r.nome + ': altura ' + r.altura + ' cm, peso ' + r.peso + ' kg, caimento ' + (r.caimento || 'normal');
        return 'Preenchi o formulário de tamanho';
      }
      return null;
    }
    case 'button':
      return (m.button || {}).text || '';
    case 'image':
      return '[FOTO RECEBIDA] O cliente mandou uma foto' + ((m.image || {}).caption ? ', com a legenda: ' + m.image.caption : '.');
    case 'order': {
      const o = m.order || {};
      const itens = (o.product_items || []).map((x) => x.quantity + 'x ' + x.product_retailer_id).join(', ');
      return 'Montei um carrinho e quero fechar: ' + itens + (o.text ? '. ' + o.text : '');
    }
    case 'audio':
      return '[ÁUDIO] O cliente mandou um áudio, que você não consegue ouvir.';
    case 'video': case 'document': case 'sticker': case 'location': case 'contacts':
      return '[ARQUIVO] O cliente mandou um arquivo (' + m.type + ') que você não consegue abrir.';
    default:
      return null; // reação, mensagem de sistema, tipo não suportado: a Lia não responde
  }
};

const saida = [];
for (const entry of corpo.entry || []) {
  for (const ch of entry.changes || []) {
    const v = ch.value || {};
    const nomes = {};
    for (const c of v.contacts || []) nomes[c.wa_id] = (c.profile || {}).name || '';
    for (const m of v.messages || []) {
      const texto = traduzir(m);
      if (texto === null || texto === '') continue;
      saida.push({ json: {
        evento: 'mensagem', wamid: m.id, sessao: 'wa:' + String(m.from).replace(/\D/g, ''),
        nome: nomes[m.from] || '', tipo: m.type, texto: String(texto).slice(0, 2000), payload: m,
      } });
    }
    for (const s of v.statuses || []) {
      const erro = (s.errors || []).map((e) => [e.code, e.title, (e.error_data || {}).details].filter(Boolean).join(' ')).join('; ');
      saida.push({ json: { evento: 'status', wamid: s.id, status: s.status, erro } });
    }
  }
}
return saida;

// Junta a resposta da Lia com a conversa de origem (mesma ordem das mensagens)
const entradas = $('Mensagem para a Lia').all();
const cfg = $('Configuração do WhatsApp').first().json.cfg;
return $input.all().map((it, i) => ({ json: {
  sessao: entradas[i].json.sessao, cfg,
  blocos: (it.json.blocos || []).length ? it.json.blocos : [{ tipo: 'texto', texto: 'Desculpa, tive um probleminha aqui. Pode repetir?', botoes: [] }],
} }));

// Monta o pedido para o modelo de imagem: a selfie do cliente + a foto da peça.
const cfg = $('Configuração do WhatsApp').first().json.cfg;
const base = $('Tem provador?').first(0).json;
const bloco = (base.blocos || []).find((b) => b.tipo === 'provador') || {};
const p = bloco.produto || {};
const bin = ($input.first().binary || {}).data;
if (!bin) return [{ json: { corpo: null, motivo: 'foto não baixada' } }];
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mime = /^image\//.test(bin.mimeType || '') ? bin.mimeType : 'image/jpeg';
const instrucao = 'Virtual try-on for a sports store. The FIRST image is a photo of a customer. The SECOND image is a product photo of "'
  + p.nome + '". Create one photorealistic image of the same person from the first photo wearing exactly this garment from the second photo. '
  + 'Keep the face, identity, hair, skin tone, body shape, pose, expression and background unchanged. '
  + 'Reproduce the garment faithfully: colors, crest and logo positions, stripes, collar and sleeves, with natural fabric folds and lighting. '
  + 'Do not add text, watermarks or other people.';
return [{ json: { corpo: {
  model: cfg.provador_modelo || 'google/gemini-3.1-flash-image',
  modalities: ['image', 'text'],
  messages: [{ role: 'user', content: [
    { type: 'text', text: instrucao },
    { type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + buf.toString('base64') } },
    { type: 'image_url', image_url: { url: p.imagem } },
  ] }],
} } }];

// Pega a imagem gerada (data URL em base64) e transforma em arquivo para subir no WhatsApp.
const r = $json || {};
const msg = (((r.choices || [])[0] || {}).message) || {};
const img = (msg.images || [])[0] || {};
const dataUrl = (img.image_url || {}).url || img.url || '';
const m = /^data:(image\/[a-z0-9.+-]+);base64,([\s\S]+)$/i.exec(dataUrl);
if (!m) {
  const erro = r.error ? (r.error.message || JSON.stringify(r.error)) : 'o modelo não devolveu imagem';
  return [{ json: { ok: false, motivo: String(erro).slice(0, 300) } }];
}
const ext = m[1].split('/')[1].replace('jpeg', 'jpg');
return [{
  json: { ok: true, mime: m[1], bytes: Math.round(m[2].length * 3 / 4) },
  binary: { data: { data: m[2], mimeType: m[1], fileName: 'previa.' + ext } },
}];

// Troca o bloco "provador" pela prévia pronta (ou pelo aviso de que não deu certo).
const cfg = $('Configuração do WhatsApp').first().json.cfg;
const base = $('Tem provador?').first(0).json;
const lp = $('Ler prévia').isExecuted ? $('Ler prévia').first().json : $input.first().json;
const real = cfg.whatsapp_modo === 'real';
const mediaId = $('Subir prévia').isExecuted ? (($('Subir prévia').first().json || {}).id || null) : null;
const ok = !!lp.ok && (!real || !!mediaId);
const blocos = [];
for (const b of base.blocos || []) {
  if (b.tipo !== 'provador') { blocos.push(b); continue; }
  if (b.texto) blocos.push({ tipo: 'texto', texto: b.texto, botoes: [] });
  blocos.push({ tipo: 'previa', ok, media_id: mediaId, produto: b.produto, bytes: lp.bytes || 0,
    motivo: ok ? null : (lp.motivo || 'falha ao subir a imagem') });
}
return [{ json: { ...base, blocos } }];

// Converte os blocos da Lia em mensagens da API oficial do WhatsApp (Cloud API).
// Com catálogo da Meta (whatsapp_catalogo_id): fichas e listas nativas de produto.
// Sem catálogo: foto + preço + botões de resposta, que funcionam em qualquer conta.
const corta = (s, n) => { s = String(s ?? '').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const brl = (v) => (v == null ? '' : 'R$ ' + Number(v).toFixed(2).replace('.', ','));
// Negrito do WhatsApp é *assim*; link em markdown vira "texto: link"
const md = (s) => String(s ?? '')
  .replace(/\*\*([^*]+)\*\*/g, '*$1*')
  .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1: $2');
const idAcao = (acao, p) => corta(acao + '|' + p.item_group_id + '|' + p.nome, 256);
const ficha = (p) => {
  const promo = p.preco_original && p.preco_original > p.preco ? '~' + brl(p.preco_original) + '~ ' : '';
  return '*' + p.nome + '*\n' + promo + brl(p.preco) + (p.parcelamento ? ' no cartão (' + p.parcelamento + ')' : '')
    + (p.preco_pix ? '\nou ' + brl(p.preco_pix) + ' no Pix' : '')
    + ((p.tamanhos || []).length ? '\nTamanhos: ' + p.tamanhos.join(', ') : '');
};
const artigo = (nome) => (/^\S*a\b/i.test(String(nome || '').trim()) ? 'a' : 'o');
const linkVideo = (u) => String(u || '').replace('youtube.com/embed/', 'youtube.com/watch?v=');
const rotulos = { material: 'Material', gola: 'Gola', escudo: 'Escudo', manga: 'Manga' };

const saida = [];
for (const item of $input.all()) {
  const { sessao, blocos = [], cfg = {} } = item.json;
  const to = String(sessao || '').replace(/^wa:/, '');
  const real = cfg.whatsapp_modo === 'real';
  const url = 'https://graph.facebook.com/' + (cfg.whatsapp_graph_versao || 'v23.0') + '/' + (cfg.whatsapp_phone_number_id || 'SEM-PHONE-NUMBER-ID') + '/messages';
  const cat = String(cfg.whatsapp_catalogo_id || '').trim();
  const flowId = String(cfg.whatsapp_flow_tamanho_id || '').trim();
  const baseN8n = String(cfg.url_base_n8n || '').replace(/\/$/, '');
  const msgs = [];

  const texto = (t) => { t = md(t).trim(); while (t) { msgs.push({ type: 'text', text: { body: t.slice(0, 4096), preview_url: true } }); t = t.slice(4096); } };
  const botoes = (corpo, lista, header) => msgs.push({ type: 'interactive', interactive: {
    type: 'button', ...(header ? { header } : {}), body: { text: corta(md(corpo), 1024) },
    action: { buttons: lista.slice(0, 3).map((b, i) => ({ type: 'reply', reply: { id: corta(b.id || 'b' + i, 256), title: corta(b.titulo, 20) } })) },
  } });
  const imagem = (link, legenda) => { if (/^https?:\/\//.test(link || '')) msgs.push({ type: 'image', image: { link, ...(legenda ? { caption: corta(md(legenda), 1024) } : {}) } }); };
  const linkBotao = (corpo, rotulo, link) => msgs.push({ type: 'interactive', interactive: {
    type: 'cta_url', body: { text: corta(md(corpo), 1024) }, action: { name: 'cta_url', parameters: { display_text: corta(rotulo, 20), url: link } },
  } });
  // Cartão de produto sem catálogo: foto no topo, preço no corpo e 3 botões
  const cartao = (p, extra) => botoes((extra ? extra + '\n\n' : '') + ficha(p), [
    { id: idAcao('quero', p), titulo: 'Quero essa' },
    { id: idAcao('fotos', p), titulo: 'Ver mais fotos' },
    { id: idAcao('tam', p), titulo: 'Qual meu tamanho?' },
  ], /^https?:\/\//.test(p.imagem || '') ? { type: 'image', image: { link: p.imagem } } : null);
  // No catálogo da Meta cada tamanho é um item; a ficha abre no primeiro tamanho com estoque
  const codigoMeta = (p) => (p.skus || [])[0] || p.item_group_id;
  const fichaNativa = (p, corpo) => msgs.push({ type: 'interactive', interactive: {
    type: 'product', ...(corpo ? { body: { text: corta(md(corpo), 1024) } } : {}),
    action: { catalog_id: cat, product_retailer_id: codigoMeta(p) },
  } });
  const listaNativa = (cabecalho, corpo, secoes) => msgs.push({ type: 'interactive', interactive: {
    type: 'product_list', header: { type: 'text', text: corta(cabecalho || 'Olden Sports', 60) },
    body: { text: corta(md(corpo) || 'Dá uma olhada 👇', 1024) },
    action: { catalog_id: cat, sections: secoes.slice(0, 10).map((s) => ({ title: corta(s.titulo, 24), product_items: s.produtos.map((p) => ({ product_retailer_id: codigoMeta(p) })) })) },
  } });

  for (const b of blocos) {
    const p = b.produto || {};
    switch (b.tipo) {
      case 'texto':
        if ((b.botoes || []).length) botoes(b.texto, b.botoes.map((x) => ({ id: x.id, titulo: x.titulo })));
        else texto(b.texto);
        break;
      case 'menu':
        msgs.push({ type: 'interactive', interactive: {
          type: 'list', body: { text: corta(md(b.corpo), 1024) },
          action: { button: corta(b.botao || 'Ver opções', 20), sections: [{ title: 'Opções', rows: (b.opcoes || []).slice(0, 10).map((o, i) => ({
            id: corta(o.id || 'op' + i, 200), title: corta(o.titulo, 24), ...(o.descricao ? { description: corta(o.descricao, 72) } : {}),
          })) }] },
        } });
        break;
      case 'produto':
        if (cat) { if (b.texto) texto(b.texto); fichaNativa(p); } else cartao(p, b.texto);
        break;
      case 'carrossel_produtos': {
        const ps = (b.produtos || []).slice(0, 10);
        if (cat) listaNativa('Separei pra você', b.corpo, [{ titulo: 'Sugestões', produtos: ps }]);
        else { if (b.corpo) texto(b.corpo); ps.slice(0, 5).forEach((x) => cartao(x)); }
        break;
      }
      case 'vitrine': {
        const secoes = (b.secoes || []).map((s) => ({ titulo: s.titulo, produtos: s.produtos || [] }));
        if (cat) listaNativa(b.cabecalho, b.corpo, secoes);
        else {
          // Sem catálogo: lista interativa (até 10 peças); tocar numa peça é o mesmo que "Quero essa"
          let resta = 10;
          const sections = secoes.map((s) => {
            const rows = s.produtos.slice(0, resta).map((x) => ({ id: idAcao('quero', x), title: corta(x.nome, 24), description: corta(brl(x.preco) + (x.preco_pix ? ' · Pix ' + brl(x.preco_pix) : ''), 72) }));
            resta -= rows.length;
            return { title: corta(s.titulo, 24), rows };
          }).filter((s) => s.rows.length);
          msgs.push({ type: 'interactive', interactive: {
            type: 'list', header: { type: 'text', text: corta(b.cabecalho || 'Vitrine', 60) },
            body: { text: corta(md(b.corpo) || 'Toque para ver as peças 👇', 1024) },
            action: { button: 'Ver peças', sections },
          } });
        }
        break;
      }
      case 'catalogo':
        if (cat) msgs.push({ type: 'interactive', interactive: { type: 'catalog_message', body: { text: corta(md(b.corpo), 1024) }, action: { name: 'catalog_message' } } });
        else linkBotao(b.corpo, 'Ver catálogo', 'https://www.oldensports.com.br/');
        break;
      case 'midias': {
        const fotos = (p.imagens || []).map((i) => i.url).filter(Boolean).slice(0, 5);
        fotos.forEach((u, i) => imagem(u, i === 0 ? (b.texto || p.nome) : ''));
        if (p.video) texto('🎥 Vídeo: ' + linkVideo(p.video));
        break;
      }
      case 'comparacao': {
        if (b.texto) texto(b.texto);
        (b.produtos || []).forEach((x) => imagem(x.imagem, ficha(x) + Object.keys(rotulos).filter((k) => (x.atributos || {})[k])
          .map((k) => '\n' + rotulos[k] + ': ' + String(x.atributos[k]).replace(/^[^:]{0,20}:\s*/, '')).join('')));
        if (baseN8n && (b.skus || []).length === 2) linkBotao('Quer ver as duas lado a lado?', 'Ver lado a lado', baseN8n + '/webhook/olden-comparacao?a=' + encodeURIComponent(b.skus[0]) + '&b=' + encodeURIComponent(b.skus[1]));
        break;
      }
      case 'tamanho': {
        const crianca = p.faixa_etaria === 'infantil' || p.faixa_etaria === 'bebe';
        if (flowId) {
          msgs.push({ type: 'interactive', interactive: {
            type: 'flow', body: { text: corta(md(b.texto) || 'Me conta suas medidas que eu te digo o tamanho', 1024) },
            action: { name: 'flow', parameters: {
              flow_message_version: '3', flow_id: flowId, flow_cta: 'Ver meu tamanho',
              mode: cfg.whatsapp_flow_modo === 'published' ? 'published' : 'draft',
              flow_token: corta('tamanho|' + sessao + '|' + p.item_group_id, 200),
              flow_action: 'navigate',
              flow_action_payload: { screen: 'TAMANHO', data: { sku: p.item_group_id, nome: corta(p.nome, 80), adulto: !crianca, crianca } },
            } },
          } });
        } else {
          texto((b.texto ? b.texto + '\n\n' : '') + (crianca ? 'Me conta a idade da criança 😊' : 'Me conta sua altura, seu peso e se você gosta mais justa, normal ou solta 😊'));
        }
        break;
      }
      case 'pagamento':
        linkBotao(b.texto, 'Pagar agora', b.url);
        break;
      case 'previa':
        // Resultado do provador (montado em "Juntar prévia")
        if (b.ok) {
          const legenda = '✨ Prévia gerada por IA: você com ' + artigo(p.nome) + ' ' + p.nome + '. Sua foto já foi apagada.';
          if (b.media_id) msgs.push({ type: 'image', image: { id: b.media_id, caption: corta(legenda, 1024) } });
          else msgs.push({ type: 'image', image: { id: 'SIMULADO', caption: legenda }, _simulacao: 'prévia gerada com ' + Math.round((b.bytes || 0) / 1024) + ' KB' });
          botoes('Curtiu? 😊', [{ id: idAcao('quero', p), titulo: 'Quero essa' }, { id: idAcao('tam', p), titulo: 'Qual meu tamanho?' }]);
        } else {
          texto(b.motivo === 'sem_foto'
            ? 'Não achei a sua foto aqui 😕 Me manda a selfie de novo?'
            : 'Poxa, não consegui gerar a prévia agora 😕 Quer tentar com outra foto, de frente e com boa luz?');
        }
        break;
      case 'provador':
        // Só chega aqui se o provador estiver desligado (provador_ativo diferente de "sim")
        texto('O provador virtual está desligado no momento 😕 Mas te ajudo com o tamanho e as fotos da peça!');
        break;
      default:
        if (b.texto || b.corpo) texto(b.texto || b.corpo);
    }
  }

  for (const m of msgs) {
    const { _simulacao, ...msg } = m;
    const resumo = msg.type === 'text' ? msg.text.body
      : msg.type === 'image' ? '[imagem] ' + (msg.image.caption || msg.image.link || '')
      : '[' + msg.interactive.type + '] ' + ((msg.interactive.body || {}).text || '');
    saida.push({ json: {
      sessao, url, real, tipo: msg.type === 'interactive' ? 'interactive:' + msg.interactive.type : msg.type,
      texto: corta(resumo, 500) + (_simulacao ? ' (' + _simulacao + ')' : ''),
      status: real ? 'enviando' : 'simulada',
      payload: { messaging_product: 'whatsapp', recipient_type: 'individual', to, ...msg },
    } });
  }
}
return saida;

// Junta a resposta da Meta com a mensagem enviada (uma por item)
const env = $('Montar envios').item.json;
const r = $json.body || {};
const ok = $json.statusCode >= 200 && $json.statusCode < 300 && (r.messages || []).length > 0;
const e = r.error || {};
return { json: { ...env, wamid: ok ? r.messages[0].id : null, status: ok ? 'enviada' : 'erro',
  erro: ok ? null : (e.message || 'HTTP ' + $json.statusCode) + (e.error_data ? ' - ' + JSON.stringify(e.error_data) : '') } };

return $input.all().filter((i) => i.json.sessao).map((i) => ({ json: {
  sessao: i.json.sessao, cfg: i.json.cfg,
  blocos: (i.json.blocos || []).length ? i.json.blocos : [{ tipo: 'texto', texto: i.json.texto, botoes: [] }],
} }));
